import * as React from "react"
import { X } from "lucide-react"
import { cva, type VariantProps } from "class-variance-authority"

import { cn } from "@/lib/utils"

const badgeVariants = cva("inline-flex items-center gap-1 rounded-[12px] font-medium", {
  variants: {
    variant: {
      color: "bg-[#26453f] text-white",
      neutral: "bg-[#f1f1f1] text-black",
      "outline-color": "border border-[#26453f] bg-white text-[#26453f]",
      "outline-neutral": "border border-[#dcdcde] bg-white text-black",
      success: "bg-[#e8f6ed] text-[#307f4a]",
      warning: "bg-[#fff0d8] text-[#e49614]",
      destructive: "bg-[#fceaea] text-[#e73f3f]",
    },
    size: {
      default: "px-2 py-0.5 text-[12px] leading-[16px]",
      large: "px-2 py-1 text-[14px] leading-[20px]",
    },
  },
  defaultVariants: {
    variant: "color",
    size: "default",
  },
})

type BadgeVariant = NonNullable<VariantProps<typeof badgeVariants>["variant"]> | "default" | "secondary" | "outline"

export interface BadgeProps
  extends React.HTMLAttributes<HTMLDivElement>,
    Omit<VariantProps<typeof badgeVariants>, "variant"> {
  variant?: BadgeVariant
  leftIcon?: React.ReactNode
  rightIcon?: React.ReactNode
  showX?: boolean
  onXClick?: React.MouseEventHandler<HTMLButtonElement>
  xIcon?: React.ReactNode
  bgColor?: string
  textColor?: string
  borderColor?: string
}

function Badge({
  className,
  variant,
  size,
  leftIcon,
  rightIcon,
  showX = false,
  onXClick,
  xIcon,
  bgColor,
  textColor,
  borderColor,
  style,
  children,
  ...props
}: BadgeProps) {
  const normalizedVariant: VariantProps<typeof badgeVariants>["variant"] =
    variant === "default"
      ? "color"
      : variant === "secondary"
      ? "neutral"
      : variant === "outline"
      ? "outline-neutral"
      : variant

  const xSizeClass = size === "large" ? "h-4 w-4" : "h-3 w-3"

  const customStyle: React.CSSProperties | undefined =
    bgColor || textColor || borderColor
      ? {
          backgroundColor: bgColor,
          color: textColor,
          borderColor,
          ...style,
        }
      : style

  return (
    <div
      className={cn(
        badgeVariants({ variant: normalizedVariant, size }),
        borderColor ? "border" : undefined,
        className
      )}
      style={customStyle}
      {...props}
    >
      {leftIcon ? <span className="inline-flex items-center">{leftIcon}</span> : null}
      <span>{children}</span>
      {rightIcon ? <span className="inline-flex items-center">{rightIcon}</span> : null}
      {showX ? (
        onXClick ? (
          <button
            type="button"
            aria-label="Remove"
            onClick={onXClick}
            className="inline-flex items-center"
          >
            {xIcon || <X className={xSizeClass} />}
          </button>
        ) : (
          <span className="inline-flex items-center">
            {xIcon || <X className={xSizeClass} />}
          </span>
        )
      ) : null}
    </div>
  )
}

export { Badge, badgeVariants }
